import type { CodeListEntry } from './codeList'

/**
 * Industrial classification: ISIC Rev. 4 at Oman's 6-digit national level, the activity of the
 * business issuing the invoice (IBR-081-OM). Chosen once in Settings › Company; the backend
 * copies it onto every line at submission, so the invoice form never asks for it.
 *
 * The 1,819 codes and English names of the published PINT-OM list (docs.peppol.eu, PINT-OM
 * invoice code list "ISIC"), the same codes the backend validates against. The Arabic names are not
 * published by PINT-OM: they are translated from the English by the project (one dictionary, in the
 * backend repository at scripts/codelists/pint-om-arabic-names.json) and are pending review.
 *
 * TODO(backend): replace with `GET /v1/code-lists/isic?q=` (searched by activity name).
 */
export type IsicActivity = CodeListEntry

const a = (code: string, en: string, ar: string = en): IsicActivity => ({ code, en, ar })

